{"ROBBERY_SHUT_UP","reg=raider|tmp=predator,seasoned",{"Shut the hell up! You'll bring every dead thing in {town} down on us!","Quiet! One more peep and I cut your tongue out!","Shut your mouth, meat! Nobody's coming!","Yell again, I dare you - go on","SHUT UP! You want the dead here too?!","Keep squealing, see what it gets you","Close that hole in your face!","Holler one more time and it's your last holler!"}},
{"ROBBERY_SHUT_UP","reg=gang|tmp=predator,seasoned",{"Shut the hell up, {g:man|lady}!","Ay, shut up! Ain't nobody gonna save you!","You screaming for who? Shut up!","Pipe down or I'll shut you up myself!","Hush! You want them things coming round the corner?","Stop yelling! You making this worse!","Say one more word - one more","Keep quiet! This ain't no block party!"}},
{"ROBBERY_SHUT_UP","reg=club|tmp=predator,seasoned,veteran",{"Hush now, nobody out here's listening but us","Quiet, friend, you're drawing a crowd, and not the friendly kind","That's enough noise, one more and it's the last","Lower the volume, {g:pal|lady}, them dead folks got good ears","Easy on the hollering, I got a headache and a short fuse"}},
{"ROBBERY_SHUT_UP","reg=club|role=biker_boss",{"Quit your hollering, you'll have every one of them stumbling over here"}},
{"ROBBERY_SHUT_UP","reg=club|tmp=predator",{"Shut your trap, hoss!","Shut up before I shut you up!"}},
{"ROBBERY_SHUT_UP","reg=crime|tmp=seasoned,predator",{"Please stop shouting, it's unprofessional, and it's dangerous","Quiet, you're attracting attention neither of us can afford","Shut up, that counts as a warning, and you don't get many","Not another sound out of you, got it?","Shut your mouth and you walk out of this","Shouting won't renegotiate anything - quiet"}},
{"ROBBERY_SHUT_UP","reg=crime|tmp=seasoned,predator|world=road",{"No yelling, nobody on this road owes you a rescue"}},
{"ROBBERY_SHUT_UP","reg=prison|tmp=predator,seasoned",{"SHUT UP! Shut up shut up shut up!","Quiet! You'll get the whole cellblock on us! The dead, I mean! The dead!","Stop screaming! I can't think when people scream!","Scream again and I swear I'll give you something to scream about!","Shut the hell up! Twenty years of noise, {g:man|lady}, I want QUIET!","Hollering didn't save nobody inside either! SHUT UP!","Zip it! Zip it or I zip it for you!"}},
{"ROBBERY_SHUT_UP","reg=outlaw|tmp=seasoned,predator",{"Shut up, you're gonna get us all bit","Quit hollering, nobody's coming, I promise you that","Hush - God, you're loud","Shut your mouth, I got a headache the size of Fort Knox","Enough, one more word and I stop being nice","Yell all you want inside your head, out loud, you die"}},
{"ROBBERY_SHUT_UP","reg=raider,gang,club,crime,prison,outlaw|tmp=predator",{"Shut the hell up! Another peep and I end you!"}},
{"ROBBERY_SHUT_UP","reg=raider,gang,club,crime,prison,outlaw|tmp=seasoned",{"Quit yelling, you'll get us all killed!"}},
{"ROBBERY_SHUT_UP","tmp=fresh",{"Shh! Please be quiet! They'll hear us!","Stop yelling! Please! You're scaring me!","Be quiet! Oh God, be quiet, they come to noise!","Shut up! Sorry! Just, please, shut up!","Shh! Shh! Please! They come to noise!","Be quiet! Be quiet or we'll both be dead - do you understand me?"}},
{"ROBBERY_SHUT_UP","reg=crime,outlaw",{"Quiet, every word buys a minute neither of us wants"}},
{"ROBBERY_SHUT_UP","reg=crime,outlaw,club",{"Hush up, you want every dead one around coming for us?"}},
{"ROBBERY_SHUT_UP","reg=crime,outlaw|tmp=seasoned",{"Stop hollering, you're going to be fine, unless you keep hollering"}},
{"ROBBERY_SHUT_UP","reg=crime",{"Not another sound, I meant the two minutes - don't spend 'em yelling","Quiet, please, I dislike an audience, and so should you"}},
{"ROBBERY_SHUT_UP","reg=crime,gang,club",{"Shut it, nobody within three miles is coming, and they all hear you"}},
{"ROBBERY_SHUT_UP","reg=outlaw,club",{"Quiet down, I've got a headache and you're a big part of it"}},
